#include "module1.h"
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <inttypes.h>
#include <errno.h>
#include <limits.h>
#include <time.h>
#include <sys/stat.h>
#ifdef _WIN32
#include <io.h>
#else
#include <unistd.h>
#endif
static uint64_t mix(uint64_t x){ x^=x>>33; x*=UINT64_C(0xff51afd7ed558ccd); x^=x>>33; x*=UINT64_C(0xc4ceb9fe1a85ec53); return x^(x>>33); }
static unsigned long hashstr(const char *s){ unsigned long h=2166136261u; while(*s){h^=(unsigned char)*s++;h*=16777619u;}return h; }
static void *alloc(Database *db,size_t n){void *p=malloc(n);if(p)db->allocations++;else db->failed_allocations++;return p;}
static void dealloc(Database *db,void *p){if(p){free(p);db->frees++;}}
static int valid(const char *s,size_t max){size_t i;if(!s)return 0;for(i=0;i<max;i++){unsigned char c=(unsigned char)s[i];if(!c)return i>0;if(c<' '||c==127||c=='|'||c=='\\')return 0;}return 0;}
static int validate(const Record *r){return r&&r->id&&valid(r->name,TC_NAME)&&valid(r->plan,TC_TEXT)&&valid(r->status,TC_TEXT)&&valid(r->network,TC_TEXT);}
static Interned *intern(Database *db,const char *s){size_t h=hashstr(s)%TC_POOL_BUCKETS;Interned *p;for(p=db->pool.buckets[h];p;p=p->next)if(strcmp(p->text,s)==0){if(p->refs==SIZE_MAX)return NULL;p->refs++;return p;}p=alloc(db,sizeof(*p));if(!p)return NULL;size_t n=strlen(s)+1;p->text=alloc(db,n);if(!p->text){dealloc(db,p);return NULL;}memcpy(p->text,s,n);p->refs=1;p->next=db->pool.buckets[h];db->pool.buckets[h]=p;db->pool.unique++;db->pool.bytes+=n;return p;}
static void release(Database *db,Interned *p){if(!p)return;if(--p->refs)return;size_t h=hashstr(p->text)%TC_POOL_BUCKETS;Interned **link=&db->pool.buckets[h];while(*link&&*link!=p)link=&(*link)->next;if(*link)*link=p->next;db->pool.unique--;db->pool.bytes-=strlen(p->text)+1;dealloc(db,p->text);dealloc(db,p);}
static int acquire3(Database *db,const Record *r,Interned **a,Interned **b,Interned **c){*a=intern(db,r->plan);if(!*a)return TC_NOMEM;*b=intern(db,r->status);if(!*b){release(db,*a);return TC_NOMEM;}*c=intern(db,r->network);if(!*c){release(db,*b);release(db,*a);return TC_NOMEM;}return TC_OK;}
static Subscriber *lookup(const Database *db,uint64_t id){size_t h=mix(id)%db->capacity;for(Subscriber *p=db->buckets[h];p;p=p->next)if(p->id==id)return p;return NULL;}
static void export_record(const Subscriber *p,Record *r){memset(r,0,sizeof(*r));r->id=p->id;memcpy(r->name,p->name,strlen(p->name)+1);memcpy(r->plan,p->plan->text,strlen(p->plan->text)+1);memcpy(r->status,p->status->text,strlen(p->status->text)+1);memcpy(r->network,p->network->text,strlen(p->network->text)+1);r->created_at=p->created_at;r->updated_at=p->updated_at;}
int db_init(Database *db){if(!db)return TC_INVALID;memset(db,0,sizeof(*db));db->capacity=TC_BUCKETS;db->buckets=calloc(db->capacity,sizeof(*db->buckets));if(!db->buckets)return TC_NOMEM;if(pthread_rwlock_init(&db->lock,NULL)){free(db->buckets);db->buckets=NULL;return TC_IO;}return TC_OK;}
static void clear_unlocked(Database *db){for(size_t i=0;i<db->capacity;i++){Subscriber *p=db->buckets[i];while(p){Subscriber *n=p->next;release(db,p->plan);release(db,p->status);release(db,p->network);dealloc(db,p);p=n;}db->buckets[i]=NULL;}db->count=0;db->collisions=0;}
void db_destroy(Database *db){if(!db||!db->buckets)return;pthread_rwlock_wrlock(&db->lock);clear_unlocked(db);free(db->buckets);db->buckets=NULL;pthread_rwlock_unlock(&db->lock);pthread_rwlock_destroy(&db->lock);}
int db_add(Database *db,const Record *r){if(!db||!db->buckets||!validate(r))return TC_INVALID;pthread_rwlock_wrlock(&db->lock);if(lookup(db,r->id)){pthread_rwlock_unlock(&db->lock);return TC_DUPLICATE;}Subscriber *p=alloc(db,sizeof(*p));if(!p){pthread_rwlock_unlock(&db->lock);return TC_NOMEM;}Interned *a=NULL,*b=NULL,*c=NULL;int rc=acquire3(db,r,&a,&b,&c);if(rc){dealloc(db,p);pthread_rwlock_unlock(&db->lock);return rc;}p->id=r->id;p->created_at=r->created_at?r->created_at:time(NULL);p->updated_at=r->updated_at?r->updated_at:p->created_at;strcpy(p->name,r->name);p->plan=a;p->status=b;p->network=c;size_t h=mix(r->id)%db->capacity;if(db->buckets[h])db->collisions++;p->next=db->buckets[h];db->buckets[h]=p;db->count++;pthread_rwlock_unlock(&db->lock);return TC_OK;}
int db_update(Database *db,const Record *r){if(!db||!db->buckets||!validate(r))return TC_INVALID;pthread_rwlock_wrlock(&db->lock);Subscriber *p=lookup(db,r->id);if(!p){pthread_rwlock_unlock(&db->lock);return TC_MISSING;}Interned *a=NULL,*b=NULL,*c=NULL;int rc=acquire3(db,r,&a,&b,&c);if(rc){pthread_rwlock_unlock(&db->lock);return rc;}Interned *oa=p->plan,*ob=p->status,*oc=p->network;p->plan=a;p->status=b;p->network=c;strcpy(p->name,r->name);p->updated_at=time(NULL);release(db,oa);release(db,ob);release(db,oc);pthread_rwlock_unlock(&db->lock);return TC_OK;}
int db_delete(Database *db,uint64_t id){if(!db||!db->buckets||!id)return TC_INVALID;pthread_rwlock_wrlock(&db->lock);size_t h=mix(id)%db->capacity;Subscriber **link=&db->buckets[h];while(*link&&(*link)->id!=id)link=&(*link)->next;if(!*link){pthread_rwlock_unlock(&db->lock);return TC_MISSING;}Subscriber *p=*link;*link=p->next;release(db,p->plan);release(db,p->status);release(db,p->network);dealloc(db,p);db->count--;pthread_rwlock_unlock(&db->lock);return TC_OK;}
int db_find(Database *db,uint64_t id,Record *out){if(!db||!db->buckets||!id||!out)return TC_INVALID;pthread_rwlock_rdlock(&db->lock);const Subscriber *p=lookup(db,id);if(p)export_record(p,out);pthread_rwlock_unlock(&db->lock);return p?TC_OK:TC_MISSING;}
int db_stats(Database *db,Stats *out){if(!db||!db->buckets||!out)return TC_INVALID;pthread_rwlock_rdlock(&db->lock);memset(out,0,sizeof(*out));out->subscribers=db->count;out->unique_strings=db->pool.unique;out->string_bytes=db->pool.bytes;out->collisions=db->collisions;out->allocations=db->allocations;out->frees=db->frees;out->failed_allocations=db->failed_allocations;out->approximate_bytes=db->capacity*sizeof(Subscriber*)+db->count*sizeof(Subscriber)+TC_POOL_BUCKETS*sizeof(Interned*)+db->pool.unique*sizeof(Interned)+db->pool.bytes;for(size_t i=0;i<TC_POOL_BUCKETS;i++)for(Interned *p=db->pool.buckets[i];p;p=p->next)out->reference_total+=p->refs;pthread_rwlock_unlock(&db->lock);return TC_OK;}
int db_foreach(Database *db,int (*visit)(const Record*,void*),void *ctx){if(!db||!db->buckets||!visit)return TC_INVALID;pthread_rwlock_rdlock(&db->lock);int rc=TC_OK;for(size_t i=0;i<db->capacity&&rc==TC_OK;i++)for(Subscriber *p=db->buckets[i];p;p=p->next){Record r;export_record(p,&r);if(visit(&r,ctx)){rc=TC_IO;break;}}pthread_rwlock_unlock(&db->lock);return rc;}
int db_check(Database *db){if(!db||!db->buckets)return TC_INVALID;pthread_rwlock_rdlock(&db->lock);size_t count=0,refs=0,unique=0;int ok=1;for(size_t i=0;i<db->capacity;i++)for(Subscriber *p=db->buckets[i];p;p=p->next){count++;if(!p->plan||!p->status||!p->network||mix(p->id)%db->capacity!=i)ok=0;}for(size_t i=0;i<TC_POOL_BUCKETS;i++)for(Interned *p=db->pool.buckets[i];p;p=p->next){unique++;refs+=p->refs;if(!p->refs||hashstr(p->text)%TC_POOL_BUCKETS!=i)ok=0;}if(count!=db->count||unique!=db->pool.unique||refs!=count*3)ok=0;pthread_rwlock_unlock(&db->lock);return ok?TC_OK:TC_IO;}
